Lemma pb_call (a ra pv h : Z) (fxq : FPState) Rq Mq mdq crq kq :
  inv Mq mdq crq kq a -> PESK.sp_hb P h -> xhi + a <= h -> L5.ra_ok ra -> sp - 32 <= pv -> pv + 1 <= sp - 16 ->
  getr Rq (PMK.reg 1) = Z_to_bv 64 ra -> getr Rq (PMK.reg 2) = Z_to_bv 64 (sp - 32) ->
  getr Rq (PMK.reg 8) = Z_to_bv 64 (fb + 432) ->
  getr Rq (PMK.reg 10) = Z_to_bv 64 (fb + 488) -> getr Rq (PMK.reg 11) = Z_to_bv 64 pv -> csl Rq ->
  (forall (fx2 : FPState) R2 M2 md2 cr2 k2, inv M2 md2 cr2 k2 (a + 1) ->
